use crate::cli_input::HelpTopic;

pub(in crate::cli_input) const fn text(topic: HelpTopic) -> &'static str {
    match topic {
        HelpTopic::RefactorAddParameter => {
            "Append a checked parameter and an explicit argument to every supported direct call.\n\nUsage:\n  fpas refactor add-parameter <selector> --name <identifier> --type <type-expression> --mode <value|var> --argument <expression> [--context <manifest>] [--std-lib <dir>] [--out <plan.json>] [--timeout <seconds>]\n\nSelectors: file.fpas:line:column, --symbol <name>, --target-ref <file>.\nName selection requires a manifest. Lines and Unicode-scalar columns start at 1.\nType and argument must be complete FPAS fragments; quote them for your shell.\nFor var, provide unmarked writable storage; the generator inserts var and any\nnamed label. Each caller resolves its own argument. Existing arguments keep\ntheir order; the new argument runs last when reached and may fail or propagate.\nSupports non-generic named functions/procedures, recursion, import aliases,\nnested routines and non-generic record defaults. Callable values, callbacks,\nunresolved invocations, generic owners, methods and spawns block the whole plan.\nOnly selected consumers are validated. Preparation never writes source.\nDefault preparation timeout: 30 seconds. No interactive confirmation.\n\nExample:\n  fpas refactor add-parameter --symbol App.Math.Clamp --context app.fpasprj --name Offset --type integer --mode value --argument '0' --out parameter.plan.json\n  fpas refactor apply --plan parameter.plan.json\n"
        }
        HelpTopic::RefactorRename => {
            "Prepare a checked rename without changing source.\n\nUsage:\n  fpas refactor rename <selector> --name <identifier> [--context <manifest>] [--std-lib <dir>] [--out <plan.json>] [--timeout <seconds>]\n\nSelectors: file.fpas:line:column, --symbol <name>, --target-ref <file>.\nName selection requires a manifest. Lines and Unicode-scalar columns start at 1.\nThe complete preview is JSON; apply it with fpas refactor apply --plan <file>.\nDefault preparation timeout: 30 seconds. No interactive confirmation.\n\nExample:\n  fpas refactor rename --symbol App.Math.Clamp --name Bound --context app.fpasprj --out rename.plan.json\n"
        }
        HelpTopic::RefactorExtract => {
            "Prepare extraction of an expression into an immutable local binding.\n\nUsage:\n  fpas refactor extract-variable --range <file.fpas:start-line:start-column:end-line:end-column> [--context <manifest>] [--std-lib <dir>] [--out <plan.json>] [--timeout <seconds>]\n\nRanges are half-open, one-based Unicode scalars. The plan includes the generated\nname. Extraction preserves evaluation order and frequency; unsupported selections\nreturn blockers. Default timeout: 30 seconds. Preparation changes no source.\n\nExample:\n  fpas refactor extract-variable --range src/main.fpas:12:18:12:25 --out extract.plan.json\n"
        }
        HelpTopic::RefactorImports => {
            "Prepare sorting and removal of safe unused imports.\n\nUsage:\n  fpas refactor organize-imports <file.fpas> [--context <manifest>] [--std-lib <dir>] [--out <plan.json>] [--timeout <seconds>]\n\nPreserves aliases and initialization order. Comments within uses can prevent\norganization. Already organized imports return no_change with an empty plan.\nDefault timeout: 30 seconds. Preparation changes no source.\n\nExample:\n  fpas refactor organize-imports src/main.fpas --context app.fpasprj --out imports.plan.json\n"
        }
        HelpTopic::RefactorApply => {
            "Revalidate a checked plan and publish its exact source replacements.\n\nUsage:\n  fpas refactor apply --plan <plan.json> [--timeout <seconds>]\n\nThe file must be a complete schema-2 preview envelope (maximum 8 MiB).\nRechecks all inputs and regenerates the recipe. Complete matching after state\nreturns already_applied; partial or unrelated changes return stale_plan.\nDefault preparation timeout: 30 seconds. After replacement starts, publication\nand recovery finish independently of that deadline. Multi-file writes are not\ncrash-atomic. Inspect publication paths and recovery errors on failure.\n\nExample:\n  fpas refactor apply --plan rename.plan.json\n"
        }
        _ => {
            "Prepare and apply checked source refactorings as schema-2 JSON.\n\nUsage:\n  fpas refactor <rename | add-parameter | extract-variable | organize-imports | apply> [options]\n\nPreparation changes no source. --out atomically saves the same complete preview\nprinted on stdout; an identical existing artifact is accepted. Use apply --plan\nto publish after revalidation. No interactive prompts or automatic saves.\nExits: 0 prepared/no-change/applied/already-applied, 1 invalid or unsupported,\n3 incomplete analysis, deadline, worker or publication failure.\n\nExamples:\n  fpas refactor rename src/math.fpas:4:17 --name Compute --out rename.plan.json\n  fpas refactor apply --plan rename.plan.json\n  fpas refactor add-parameter --help\n"
        }
    }
}
